package lib
type hidden struct{}
func (*hidden) Read(name string) string { return name }
type other struct{}
func (*other) Read(name string) string { return name }
type Maps[K comparable] interface{ ~map[K]*hidden }
type State[K comparable,S Maps[K]] struct {
 Values S
 private S
 Nested struct{ Values S }
 Slots [2]S
}

package main
import bounds "example.test/project/lib"
type Holder[K comparable,S bounds.Maps[K]] struct {
 bounds.State[K,S]
 Rows []bounds.State[K,S]
}

package main
import bounds "example.test/project/other"
var _ = bounds.Public
type hidden struct{}
func (hidden) Read(name int) string { return "" }
func (box *Holder[K,S]) Probe() {
 for _, direct := range box.Values {
  direct.Read("direct")
 }
 for _, nested := range box.Nested.Values {
  nested.Read("nested")
 }
 for _, indexed := range box.Rows[0].Values {
  indexed.Read("index")
 }
 for _, sliced := range box.Slots[:][0] {
  sliced.Read("slice")
 }
 for _, indirect := range (*box).Values {
  indirect.Read("indirect")
 }
 copied := box
 for _, copiedValue := range copied.Values {
  copiedValue.Read("copy")
 }
 for _, row := range box.Rows {
  for _, nestedValue := range row.Values {
   nestedValue.Read("nested range")
  }
 }
}

